<?php declare(strict_types=1); ?>
<form class="quote-form" data-product="<?=$e($product['id'])?>" data-variant="<?=$e($variant['id'])?>" data-locale="<?=$lang?>" data-transport="<?=$e(json_encode(isset($product['transport'])?$product['transport']+['roundTrip'=>!empty($variant['roundTrip'])]:null,JSON_THROW_ON_ERROR))?>" data-schedule="<?=$e(json_encode(['timeSlots'=>$variant['timeSlots'] ?? [],'schedulePeriods'=>$variant['schedulePeriods'] ?? [],'saleWindow'=>$variant['saleWindow'] ?? (object)[]],JSON_THROW_ON_ERROR))?>"><fieldset><legend><?=$en?'Check price & availability':'Kiểm tra giá & số suất'?></legend><label><?=$en?'Visit date':'Ngày sử dụng'?><input type="date" name="date" required></label>
<?php if(isset($product['transport'])):?><div class="contact-form-grid"><label><?=$en?'Pickup address':'Địa chỉ đón'?><input name="pickup" required minlength="3" maxlength="300"></label><label><?=$en?'Drop-off address':'Địa chỉ trả'?><input name="dropoff" required minlength="3" maxlength="300"></label><label><?=$en?'Pickup time':'Giờ đón'?><input name="pickupTime" type="time" required></label><label><?=$en?'Passengers':'Số hành khách'?><input name="passengers" type="number" min="1" max="<?=$e($product['transport']['mode']==='PRIVATE'?($variant['maxPassengers']??1):150)?>" value="1" required></label><label><?=$en?'Flight number (optional)':'Số hiệu chuyến bay (nếu có)'?><input name="flightNumber" maxlength="40"></label><?php if(!empty($variant['roundTrip'])):?><label><?=$en?'Return date':'Ngày về'?><input name="returnDate" type="date" required></label><label><?=$en?'Return time':'Giờ về'?><input name="returnTime" type="time" required></label><?php endif;?></div><p><?=$en?'Advance booking required: ':'Nhận chuyến trước tối thiểu: '?><?=$e($product['transport']['leadMinutes'])?> <?=$en?'minutes':'phút'?></p><?php endif;?><label hidden><?=$en?'Time slot':'Suất giờ'?><select name="slotId" disabled></select></label>
<div class="quote-guests"><?php foreach($variant['prices'] as $group=>$price):if(isset($product['transport'])&&$group!=='ADULT')continue;?><label><span><?=$e(isset($product['transport'])?($product['transport']['mode']==='PRIVATE'?($en?'Trips (one vehicle)':'Chuyến (một xe)'):($en?'Seats':'Số chỗ')):($groups[$group] ?? $group))?></span><input type="number" min="<?=isset($product['transport'])?1:0?>" max="<?=isset($product['transport'])&&$product['transport']['mode']==='PRIVATE'?1:50?>" step="1" required data-group="<?=$e($group)?>" value="<?=isset($product['transport'])?'1':($group===array_key_first($variant['prices'])?'1':'0')?>"></label><?php endforeach;?></div><label><?=$en?'Voucher code (optional)':'Mã giảm giá (không bắt buộc)'?><input name="voucherCode" type="text" maxlength="40" autocomplete="off" placeholder="<?=$en?'Enter code':'Nhập mã'?>"></label><button type="submit" class="button"><?=$en?'Check price':'Kiểm tra giá'?> ↗</button></fieldset><div class="quote-result" role="status" hidden></div><small class="price-note"><?=$en?'Checking does not reserve places or create an order.':'Kiểm tra giá chưa giữ chỗ hoặc tạo đơn.'?></small><noscript><p><?=$en?'Enable JavaScript to check prices.':'Bật JavaScript để kiểm tra giá.'?></p></noscript></form>
